"""Regenerates the FB2 (FictionBook) test fixtures with Calibre's ebook-convert.

Converts the synthetic Kindle source book (../kindle/sample.epub, regenerated by
../kindle/make-fixtures.py) to sample.fb2, and stores it zipped as sample.fb2.zip, the way FB2 books
are usually distributed. All content is original test material.
"""
import subprocess, zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
SOURCE = HERE.parent / 'kindle' / 'sample.epub'

subprocess.run(['ebook-convert', str(SOURCE), str(HERE / 'sample.fb2')], check=True, stdout=subprocess.DEVNULL)
with zipfile.ZipFile(HERE / 'sample.fb2.zip', 'w', zipfile.ZIP_DEFLATED) as z:
    z.write(HERE / 'sample.fb2', 'The Lantern Keeper.fb2')
# Hand-written FictionBook with footnotes (a second <body name="notes">), a poem, and Cyrillic text,
# saved in windows-1251 as many FB2 files are.
NOTES = '''<?xml version="1.0" encoding="windows-1251"?>
<FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0" xmlns:l="http://www.w3.org/1999/xlink">
<description><title-info><genre>prose</genre><author><first-name>Анна</first-name><last-name>Тестова</last-name></author>
<book-title>Маяк и море</book-title><lang>ru</lang></title-info>
<document-info><author><nickname>fixture</nickname></author><id>thingsbook-fb2-notes</id><version>1.0</version></document-info></description>
<body>
<section><title><p>Глава первая</p></title>
<p>Смотритель маяка вёл журнал<a l:href="#n1" type="note">[1]</a> каждую ночь.</p>
<p><emphasis>Курсив</emphasis> и <strong>жирный</strong> текст сохраняются.</p></section>
<section><title><p>Глава вторая</p></title>
<poem><stanza><v>Ветер над водой,</v><v>свет над тёмной волной.</v></stanza></poem></section>
</body>
<body name="notes"><title><p>Примечания</p></title>
<section id="n1"><title><p>1</p></title><p>Журнал хранился в деревянном ящике.</p></section>
</body>
</FictionBook>
'''
(HERE / 'notes-cp1251.fb2').write_bytes(NOTES.encode('cp1251'))
for name in ('sample.fb2', 'sample.fb2.zip', 'notes-cp1251.fb2'):
    print(name, (HERE / name).stat().st_size, 'bytes')
